import { Component, ElementRef, OnDestroy, computed, effect, inject, signal, untracked } from '@angular/core';
import { EMPTY, Subscription, defer, retry, timer } from 'rxjs';
import { AuthService } from '../../../auth/services/auth.service';
import { FloorPlanViewerComponent } from '../../../../shared/components/floor-plan-viewer/floor-plan-viewer.component';
import { FloorPlanResponse, FloorPlansService } from '../../../../shared/services/floor-plans.service';
import { DashboardService, DashboardSummaryResponse, RevenuePoint } from '../../../../shared/services/dashboard.service';
import { ExtratoService } from '../../../../shared/services/extrato.service';
import { LineChartComponent, LineChartPoint } from '../../../../shared/components/line-chart/line-chart.component';
import { RippleDirective } from '../../../../shared/directives/ripple.directive';
import { PedidosComponent } from '../pedidos/pedidos.component';
import { ServicosComponent } from '../servicos/servicos.component';
import { SubscriptionBannerComponent } from '../../../../shared/components/subscription-banner/subscription-banner.component';
import { SubscriptionService } from '../../../../shared/services/subscription.service';
import { QuickServiceComponent } from '../../../../shared/components/quick-service/quick-service.component';
import {
  CompanyPendingFee,
  PlatformFinanceService,
  PlatformFinanceSummary,
  PlatformOverview,
  SITUATION_LABELS,
  situationTone
} from '../../../../shared/services/platform-finance.service';
import { RouterLink } from '@angular/router';
import { brDateTimeFormat, parseApiDate } from '../../../../shared/utils/datetime.util';

const MANAGEMENT_PROFILES = ['ADMIN', 'OWNER', 'COMMERCIAL', 'MANAGER'];
// Perfis operacionais que vivem na fila de pedidos no dia a dia — a home entra direto na mesma
// visão do menu Pedidos (ver PedidosComponent) em vez do mapa do salão, pra não exigir mais um
// clique de quem só quer ver o que precisa preparar/servir agora.
const QUEUE_HOME_PROFILES = ['WAITER', 'KITCHEN'];
// Só WAITER: quem chama/atende limpeza, garçom, caixa, reclamação e ajuda de mesa — o backend nem
// libera esses endpoints pra KITCHEN (ver TableServiceRequestController#@RequireProfile).
const SERVICE_HOME_PROFILES = ['WAITER'];
// Atendimento rápido numa aba própria — QR Code da mesa ou do cartão de consumo direto para lançar
// pedido ou abrir a comanda (ver QuickServiceComponent). Garçom e caixa abrem a home nela (é a
// primeira aba deles); dono e gerente abrem na Visão geral.
const QUICK_SERVICE_PROFILES = ['WAITER', 'CASHIER', 'OWNER', 'COMMERCIAL', 'MANAGER'];
const WS_RETRY_DELAY_MS = 5000;
const WS_SILENT_RETRIES = 3;
// Troca de aba arrastando para o lado (mobile): deslocamento horizontal mínimo, bem mais
// horizontal que vertical (senão é rolagem) e gesto rápido (senão é o usuário lendo/arrastando).
const SWIPE_MIN_DISTANCE_PX = 60;
const SWIPE_MAX_DURATION_MS = 700;
// Gestos que começam nesses elementos são deles: mapa (Konva arrasta o palco), campos, câmera do
// QR e listas com rolagem horizontal própria.
const SWIPE_IGNORE_SELECTOR = 'canvas, input, textarea, select, video, [data-no-swipe]';

type DashboardTabId = 'platform' | 'overview' | 'atendimento' | 'pedidos' | 'servicos' | 'floorplan';

interface DashboardTab {
  id: DashboardTabId;
  label: string;
  icon: string;
}

interface RevenuePreset {
  label: string;
  days: number;
}

const REVENUE_PRESETS: RevenuePreset[] = [
  { label: '7 dias', days: 7 },
  { label: '30 dias', days: 30 },
  { label: '90 dias', days: 90 }
];

@Component({
  selector: 'app-admin-dashboard',
  standalone: true,
  imports: [
    FloorPlanViewerComponent,
    LineChartComponent,
    PedidosComponent,
    ServicosComponent,
    RippleDirective,
    SubscriptionBannerComponent,
    QuickServiceComponent,
    RouterLink
  ],
  templateUrl: './dashboard.component.html',
  styleUrl: './dashboard.component.scss'
})
export class DashboardComponent implements OnDestroy {
  private readonly authService = inject(AuthService);
  private readonly floorPlansService = inject(FloorPlansService);
  private readonly dashboardService = inject(DashboardService);
  private readonly subscriptionService = inject(SubscriptionService);
  private readonly extratoService = inject(ExtratoService);
  private readonly platformFinanceService = inject(PlatformFinanceService);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);

  // Crédito da assinatura — vem do SubscriptionService (REST, já carregado pelo subscriptionGuard),
  // NÃO do resumo operacional do WebSocket: o crédito não é métrica de tempo real e o payload do
  // WS passa por serializadores diferentes do REST.
  readonly subscriptionCreditAvailable = computed(() => this.subscriptionService.status()?.credit?.available ?? null);
  private readonly currencyFormatter = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
  private readonly shortDateFormatter = brDateTimeFormat({ day: '2-digit', month: '2-digit', year: 'numeric' });

  readonly currentUser = this.authService.currentUser;
  readonly selectedCompany = this.authService.selectedCompany;
  readonly revenuePresets = REVENUE_PRESETS;

  // As métricas administrativas (faturamento, comandas, ocupação de mesas, funcionários) só
  // existem no backend para ADMIN/OWNER/MANAGER (ver DashboardController, restrito por
  // @RequireProfile) — para os demais perfis (garçom, caixa, cozinha) a home mostra só o mapa do
  // salão, sem tentar abrir uma conexão que o handshake rejeitaria com 403.
  readonly isManagementProfile = computed(() => {
    const profileCode = this.selectedCompany()?.profileCode;
    return !!profileCode && MANAGEMENT_PROFILES.includes(profileCode);
  });

  // Garçom e cozinha entram direto na fila de pedidos (mesmo conteúdo do menu Pedidos, ver
  // PedidosComponent) — o mapa do salão continua abaixo, mas o que importa pra esses perfis é ver
  // e movimentar os itens assim que abrem a home.
  readonly isQueueHomeProfile = computed(() => {
    const profileCode = this.selectedCompany()?.profileCode;
    return !!profileCode && QUEUE_HOME_PROFILES.includes(profileCode);
  });

  // Garçom também entra direto nos serviços gerais (mesmo conteúdo do menu Serviços, ver
  // ServicosComponent) — logo abaixo da fila de pedidos na home.
  readonly isServiceHomeProfile = computed(() => {
    const profileCode = this.selectedCompany()?.profileCode;
    return !!profileCode && SERVICE_HOME_PROFILES.includes(profileCode);
  });

  readonly isQuickServiceProfile = computed(() => {
    const profileCode = this.selectedCompany()?.profileCode;
    return !!profileCode && QUICK_SERVICE_PROFILES.includes(profileCode);
  });

  // Indicadores operacionais, atualizados em tempo real via WebSocket (ver connectRealtime) —
  // não há mais um fetch único aqui, a conexão já recebe o estado atual ao abrir e depois a cada
  // ~10s (ver DashboardBroadcastScheduler no backend).
  readonly summary = signal<DashboardSummaryResponse | null>(null);
  readonly isLoadingSummary = signal(false);
  readonly summaryError = signal<string | null>(null);
  private summarySubscription?: Subscription;

  readonly revenueSeries = signal<RevenuePoint[]>([]);
  readonly isLoadingRevenue = signal(false);
  readonly revenueError = signal<string | null>(null);
  readonly revenueStartDate = signal(this.toIsoDate(this.daysAgo(29)));
  readonly revenueEndDate = signal(this.toIsoDate(new Date()));
  readonly activeRevenuePresetDays = signal<number | null>(30);

  readonly grossPoints = computed<LineChartPoint[]>(() =>
    this.revenueSeries().map((point) => ({ date: point.date, amount: point.amount }))
  );
  readonly netPoints = computed<LineChartPoint[]>(() =>
    this.revenueSeries().map((point) => ({ date: point.date, amount: point.netAmount ?? 0 }))
  );
  readonly revenueTotal = computed(() => this.revenueSeries().reduce((total, point) => total + point.amount, 0));
  readonly revenueNetTotal = computed(() => this.revenueSeries().reduce((total, point) => total + (point.netAmount ?? 0), 0));

  // Recebido no período por onde entrou (caixa / garçom) — resumo do extrato, mesmo período do
  // gráfico. A taxa da Comanda Única desses pagamentos é cobrada semanalmente no cartão.
  readonly cashRegisterAmount = signal<number | null>(null);
  readonly cashWaiterAmount = signal<number | null>(null);
  readonly platformFeesAmount = signal<number | null>(null);

  // Aba "Comanda Única" — só para o platform admin (User.isPlatformAdmin), independente da empresa
  // selecionada: taxas recebidas/geradas no período (PlatformFinanceService#getSummary) e o estado
  // atual de estabelecimentos e taxas pendentes por estabelecimento (#getOverview).
  readonly isPlatformAdmin = this.authService.isPlatformAdmin;
  readonly platformSummary = signal<PlatformFinanceSummary | null>(null);
  readonly platformOverview = signal<PlatformOverview | null>(null);
  readonly isLoadingPlatformSummary = signal(false);
  readonly isLoadingPlatformOverview = signal(false);
  readonly platformSummaryError = signal<string | null>(null);
  readonly platformOverviewError = signal<string | null>(null);
  readonly platformStartDate = signal(this.toIsoDate(this.daysAgo(29)));
  readonly platformEndDate = signal(this.toIsoDate(new Date()));
  readonly activePlatformPresetDays = signal<number | null>(30);
  readonly pendingFeeSearch = signal('');

  readonly platformFeePoints = computed<LineChartPoint[]>(() =>
    (this.platformSummary()?.feeSeries ?? []).map((point) => ({ date: point.date, amount: point.amount }))
  );
  readonly platformReceivedTotal = computed(() => {
    const summary = this.platformSummary();
    return summary ? summary.receivedFeeAmount + summary.receivedSubscriptionAmount : null;
  });
  readonly filteredPendingFees = computed<CompanyPendingFee[]>(() => {
    const term = this.pendingFeeSearch().trim().toLocaleLowerCase('pt-BR');
    const rows = this.platformOverview()?.pendingFeesByCompany ?? [];
    return term ? rows.filter((row) => row.tradeName?.toLocaleLowerCase('pt-BR').includes(term)) : rows;
  });

  readonly floorPlans = signal<FloorPlanResponse[]>([]);
  readonly isLoadingFloorPlans = signal(true);
  readonly selectedFloorPlanId = signal<string | null>(null);

  // Views da home organizadas em abas — cada perfil só vê as abas que fazem sentido pra ele (ver
  // isManagementProfile/isQueueHomeProfile/isServiceHomeProfile). Mapa do salão aparece pra todo
  // mundo, sempre por último. Pedidos/Serviços só ficam montados (e só abrem WebSocket) enquanto a
  // aba correspondente está ativa — trocar de aba desconecta a anterior e conecta a nova. A
  // notificação de pedido/serviço novo (som + sino no topo) não depende de qual aba está ativa —
  // ver NotificationsService, usado pelo AdminLayoutComponent.
  readonly availableTabs = computed<DashboardTab[]>(() => {
    const tabs: DashboardTab[] = [];
    if (this.isPlatformAdmin()) {
      tabs.push({ id: 'platform', label: 'Comanda Única', icon: 'account_balance' });
    }
    if (this.isManagementProfile()) {
      tabs.push({ id: 'overview', label: 'Visão geral', icon: 'insights' });
    }
    if (this.isQuickServiceProfile()) {
      tabs.push({ id: 'atendimento', label: 'Atendimento', icon: 'bolt' });
    }
    if (this.isQueueHomeProfile()) {
      tabs.push({ id: 'pedidos', label: 'Pedidos', icon: 'point_of_sale' });
    }
    if (this.isServiceHomeProfile()) {
      tabs.push({ id: 'servicos', label: 'Serviços', icon: 'support_agent' });
    }
    tabs.push({ id: 'floorplan', label: 'Mapa do salão', icon: 'map' });
    return tabs;
  });

  readonly activeTab = signal<DashboardTabId>('floorplan');
  // Sentido da última troca — a aba nova entra deslizando do lado certo.
  readonly slideDirection = signal<'next' | 'prev'>('next');
  private swipeStart: { x: number; y: number; time: number } | null = null;

  // Reage à troca de empresa (seletor do topo ou empresa recém-criada — ver
  // AdminLayoutComponent#selectCompany/onCompanyCreated), não só à primeira montagem: a home
  // sempre navega para esta mesma rota (/painel/dashboard), então se o usuário já estava aqui a
  // navegação não remonta o componente — sem reagir ao signal, os dados ficariam presos na
  // empresa anterior. Ler selectedCompany()/isManagementProfile() aqui é o que faz o efeito
  // disparar de novo a cada troca; o resto do corpo vai em untracked() para não reagir também às
  // mudanças de revenueStartDate/revenueEndDate (essas já têm seus próprios gatilhos — ver
  // applyRevenuePreset/onRevenueStartDateChange — e reagiriam aqui também, duplicando a chamada).
  constructor() {
    effect(() => {
      const companyId = this.selectedCompany()?.companyId ?? null;
      const isManagement = this.isManagementProfile();
      untracked(() => this.reloadForCompany(companyId, isManagement));
    });
  }

  private reloadForCompany(companyId: string | null, isManagement: boolean): void {
    this.summarySubscription?.unsubscribe();
    this.summary.set(null);
    this.summaryError.set(null);
    this.revenueSeries.set([]);
    this.cashRegisterAmount.set(null);
    this.cashWaiterAmount.set(null);
    this.platformFeesAmount.set(null);

    this.activeTab.set(this.availableTabs()[0]?.id ?? 'floorplan');

    if (isManagement && companyId) {
      this.connectRealtimeSummary();
      this.loadFinancialReport();
    }
    if (this.isPlatformAdmin() && !this.platformOverview()) {
      this.loadPlatformDashboard();
    }
    this.loadFloorPlans();
  }

  selectTab(tabId: DashboardTabId): void {
    const tabs = this.availableTabs();
    const from = tabs.findIndex((tab) => tab.id === this.activeTab());
    const to = tabs.findIndex((tab) => tab.id === tabId);
    this.slideDirection.set(to >= from ? 'next' : 'prev');
    this.activeTab.set(tabId);
    // A barra de abas rola na horizontal no mobile — mantém a aba ativa à vista.
    setTimeout(() => this.host.nativeElement
      .querySelector(`#dashboard-tab-${tabId}`)
      ?.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'nearest' }));
  }

  onPanelTouchStart(event: TouchEvent): void {
    const target = event.target as HTMLElement | null;
    if (event.touches.length !== 1 || !target || target.closest(SWIPE_IGNORE_SELECTOR) || this.isInsideHorizontalScroll(target)) {
      this.swipeStart = null;
      return;
    }
    const touch = event.touches[0];
    this.swipeStart = { x: touch.clientX, y: touch.clientY, time: Date.now() };
  }

  onPanelTouchEnd(event: TouchEvent): void {
    const start = this.swipeStart;
    this.swipeStart = null;
    if (!start || event.changedTouches.length === 0) {
      return;
    }
    const touch = event.changedTouches[0];
    const dx = touch.clientX - start.x;
    const dy = touch.clientY - start.y;
    if (Math.abs(dx) < SWIPE_MIN_DISTANCE_PX || Math.abs(dx) < Math.abs(dy) * 1.5
      || Date.now() - start.time > SWIPE_MAX_DURATION_MS) {
      return;
    }
    const tabs = this.availableTabs();
    const next = tabs[tabs.findIndex((tab) => tab.id === this.activeTab()) + (dx < 0 ? 1 : -1)];
    if (next) {
      this.selectTab(next.id);
    }
  }

  // Tabelas e listas que rolam na horizontal dentro da aba ficam com o gesto — só troca de aba se
  // nenhum elemento entre o toque e o painel puder rolar para o lado.
  private isInsideHorizontalScroll(element: HTMLElement): boolean {
    const panel = this.host.nativeElement.querySelector('.dashboard-panel');
    for (let node: HTMLElement | null = element; node && node !== panel; node = node.parentElement) {
      const overflowX = getComputedStyle(node).overflowX;
      if ((overflowX === 'auto' || overflowX === 'scroll') && node.scrollWidth > node.clientWidth) {
        return true;
      }
    }
    return false;
  }

  ngOnDestroy(): void {
    this.summarySubscription?.unsubscribe();
  }

  selectFloorPlan(floorPlanId: string): void {
    this.selectedFloorPlanId.set(floorPlanId);
  }

  formatCurrency(value: number | undefined | null): string {
    return value != null ? this.currencyFormatter.format(value) : '—';
  }

  applyRevenuePreset(days: number): void {
    this.activeRevenuePresetDays.set(days);
    this.revenueStartDate.set(this.toIsoDate(this.daysAgo(days - 1)));
    this.revenueEndDate.set(this.toIsoDate(new Date()));
    this.loadFinancialReport();
  }

  onRevenueStartDateChange(value: string): void {
    this.activeRevenuePresetDays.set(null);
    this.revenueStartDate.set(value);
    this.loadFinancialReport();
  }

  onRevenueEndDateChange(value: string): void {
    this.activeRevenuePresetDays.set(null);
    this.revenueEndDate.set(value);
    this.loadFinancialReport();
  }

  // Recarrega o gráfico/saldos sob demanda (botão "Atualizar") — mesmo período selecionado, sem
  // esperar o próximo carregamento automático (não há mais WebSocket alimentando o gráfico).
  refreshFinancialReport(): void {
    this.loadFinancialReport();
  }

  applyPlatformPreset(days: number): void {
    this.activePlatformPresetDays.set(days);
    this.platformStartDate.set(this.toIsoDate(this.daysAgo(days - 1)));
    this.platformEndDate.set(this.toIsoDate(new Date()));
    this.loadPlatformSummary();
  }

  onPlatformStartDateChange(value: string): void {
    this.activePlatformPresetDays.set(null);
    this.platformStartDate.set(value);
    this.loadPlatformSummary();
  }

  onPlatformEndDateChange(value: string): void {
    this.activePlatformPresetDays.set(null);
    this.platformEndDate.set(value);
    this.loadPlatformSummary();
  }

  loadPlatformDashboard(): void {
    this.loadPlatformSummary();
    this.loadPlatformOverview();
  }

  readonly situationLabels = SITUATION_LABELS;
  readonly situationTone = situationTone;

  formatShortDate(value: string | null): string {
    const date = parseApiDate(value);
    return date ? this.shortDateFormatter.format(date) : '—';
  }

  private loadPlatformSummary(): void {
    this.isLoadingPlatformSummary.set(true);
    this.platformSummaryError.set(null);
    this.platformFinanceService.getSummary(this.platformStartDate(), this.platformEndDate()).subscribe({
      next: (summary) => {
        this.platformSummary.set(summary);
        this.isLoadingPlatformSummary.set(false);
      },
      error: () => {
        this.isLoadingPlatformSummary.set(false);
        this.platformSummaryError.set('Não foi possível carregar as taxas do período selecionado.');
      }
    });
  }

  private loadPlatformOverview(): void {
    this.isLoadingPlatformOverview.set(true);
    this.platformOverviewError.set(null);
    this.platformFinanceService.getOverview().subscribe({
      next: (overview) => {
        this.platformOverview.set(overview);
        this.isLoadingPlatformOverview.set(false);
      },
      error: () => {
        this.isLoadingPlatformOverview.set(false);
        this.platformOverviewError.set('Não foi possível carregar os estabelecimentos e as taxas pendentes.');
      }
    });
  }

  private connectRealtimeSummary(): void {
    const companyId = this.selectedCompany()?.companyId;
    if (!companyId) {
      return;
    }

    this.isLoadingSummary.set(true);
    this.summaryError.set(null);

    // O WebSocket já se reconecta sozinho (retry com um pequeno atraso) se a conexão cair — não
    // precisa de um fallback por REST em paralelo. Depois de algumas tentativas seguidas sem
    // sucesso, expõe o erro na tela (mas continua tentando em segundo plano, resetando a contagem
    // após uma reconexão bem-sucedida). defer(): cada NOVA tentativa busca o token de novo em vez
    // de reusar o de quando connectRealtimeSummary foi chamado pela primeira vez — sem isso, um
    // token expirado ficava sendo reenviado pra sempre nas tentativas seguintes, martelando o
    // backend mesmo depois de um novo login. Sem token válido, desloga e para de tentar.
    this.summarySubscription = defer(() => {
      const token = this.authService.getAccessToken();
      if (!token) {
        this.authService.logout();
        return EMPTY;
      }
      return this.dashboardService.connectRealtime(companyId, token);
    })
      .pipe(
        retry({
          delay: (_, retryCount) => {
            if (retryCount >= WS_SILENT_RETRIES) {
              this.isLoadingSummary.set(false);
              this.summaryError.set('Não foi possível conectar à atualização em tempo real do painel.');
            }
            return timer(WS_RETRY_DELAY_MS);
          },
          resetOnSuccess: true
        })
      )
      .subscribe({
        next: (summary) => {
          this.summary.set(summary);
          this.isLoadingSummary.set(false);
          this.summaryError.set(null);
        },
        error: () => {
          this.isLoadingSummary.set(false);
          this.summaryError.set('Não foi possível conectar à atualização em tempo real do painel.');
        }
      });
  }

  // Gráfico de faturamento (pagamentos registrados nas comandas, bruto e líquido da taxa da
  // Comanda Única) + o recebido por caixa/garçom no mesmo período (resumo do extrato). Tudo da base
  // da Comanda Única. O WebSocket (ver connectRealtimeSummary) segue alimentando só a "Operação".
  private loadFinancialReport(): void {
    const companyId = this.selectedCompany()?.companyId;
    if (!companyId) {
      return;
    }
    this.isLoadingRevenue.set(true);
    this.revenueError.set(null);

    this.dashboardService.getRevenueSeries(this.revenueStartDate(), this.revenueEndDate()).subscribe({
      next: (series) => {
        this.revenueSeries.set(series);
        this.isLoadingRevenue.set(false);
      },
      error: () => {
        this.isLoadingRevenue.set(false);
        this.revenueError.set('Não foi possível carregar o faturamento do período selecionado.');
      }
    });

    this.extratoService.getExtrato(companyId, {
      startDate: this.revenueStartDate(),
      endDate: this.revenueEndDate(),
      size: 1
    }).subscribe({
      next: (extrato) => {
        this.cashRegisterAmount.set(extrato.resumo.recebidoCaixa);
        this.cashWaiterAmount.set(extrato.resumo.recebidoGarcom);
        this.platformFeesAmount.set(extrato.resumo.taxasComandaUnica);
      },
      error: () => {
        this.cashRegisterAmount.set(null);
        this.cashWaiterAmount.set(null);
        this.platformFeesAmount.set(null);
      }
    });
  }

  private loadFloorPlans(): void {
    this.isLoadingFloorPlans.set(true);
    this.floorPlansService.list().subscribe({
      next: (floorPlans) => {
        this.floorPlans.set(floorPlans);
        this.selectedFloorPlanId.set(floorPlans[0]?.id ?? null);
        this.isLoadingFloorPlans.set(false);
      },
      error: () => {
        this.isLoadingFloorPlans.set(false);
      }
    });
  }

  private daysAgo(days: number): Date {
    const date = new Date();
    date.setDate(date.getDate() - days);
    return date;
  }

  private toIsoDate(date: Date): string {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  }
}